{
    RoboMas_Ctrl_StructTypedef *ctrl =
        &robomas_dev_info_global[ROBOMAS_C610_COUNT].ctrl_param;
    configure_robomas_common(&robomas_dev_info_global[ROBOMAS_C610_COUNT]);

    ctrl->rotation = ROBOMAS_ROT_ACW;
